import React, { useEffect, useState, useMemo } from 'react';
import { Helmet } from 'react-helmet-async';
import InputLabel from '@mui/material/InputLabel';
import FormControl from '@mui/material/FormControl';
import Select from '@mui/material/Select';
import { useLocation } from 'react-router-dom';
import {
  Card,
  Table,
  Stack,
  Paper,
  Button,
  TableRow,
  MenuItem,
  TableBody,
  TableCell,
  Typography,
  IconButton,
  TableContainer,
  TablePagination,
  Modal,
  Switch,
  Box,
  Popover,
} from '@mui/material';
import DateFormat from '../../components/dayjsFormat/DateFormat';
import { axios } from '../../utils/axios';
import { BASE_URL } from '../../utils/config';
import { updateUrlParams } from '../../utils/urlUtilis';

// components
import Label from '../../components/label';
import Iconify from '../../components/iconify';
import Scrollbar from '../../components/scrollbar';
// sections
import { UserListHead, UserListToolbar } from '../../sections/@dashboard/user';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import useResponsive from '../../hooks/useResponsive';
import DeleteModal from '../../components/deleteModal/DeleteModal';
import TanstackTable from '../../components/tanstackMUItable/TanstackTable';
import TanstackTableV8 from '../../components/tanstackMUItable/tanstackTableV8';

const languageOptions = [
  { value: 'en', label: 'English' },
  { value: 'es', label: 'Spanish' },
  { value: 'fr', label: 'French' },
  { value: 'de', label: 'German' },
  { value: 'it', label: 'Italian' },
  { value: 'pt', label: 'Portuguese' },
  { value: 'ru', label: 'Russian' },
  { value: 'zh', label: 'Chinese (Simplified)' },
  { value: 'ja', label: 'Japanese' },
  { value: 'ko', label: 'Korean' },
  { value: 'ar', label: 'Arabic' },
  { value: 'hi', label: 'Hindi' },
  { value: 'bn', label: 'Bengali' },
  { value: 'ur', label: 'Urdu' },
  { value: 'vi', label: 'Vietlabelse' },
  { value: 'id', label: 'Indonesian' },
  { value: 'tr', label: 'Turkish' },
  { value: 'th', label: 'Thai' },
  { value: 'nl', label: 'Dutch' },
  { value: 'sv', label: 'Swedish' },
  { value: 'pl', label: 'Polish' },
  { value: 'fi', label: 'Finnish' },
  { value: 'cs', label: 'Czech' },
  { value: 'ro', label: 'Romanian' },
  { value: 'hu', label: 'Hungarian' },
  { value: 'el', label: 'Greek' },
  { value: 'da', label: 'Danish' },
  { value: 'no', label: 'Norwegian' },
  { value: 'he', label: 'Hebrew' },
  { value: 'sk', label: 'Slovak' },
  { value: 'uk', label: 'Ukrainian' },
  { value: 'lt', label: 'Lithuanian' },
  { value: 'bg', label: 'Bulgarian' },
  { value: 'hr', label: 'Croatian' },
  { value: 'sr', label: 'Serbian' },
  { value: 'sl', label: 'Slovenian' },
  { value: 'et', label: 'Estonian' },
  { value: 'lv', label: 'Latvian' },
  { value: 'sq', label: 'Albanian' },
  { value: 'mk', label: 'Macedonian' },
  { value: 'bs', label: 'Bosnian' },
  { value: 'mt', label: 'Maltese' },
  { value: 'eu', label: 'Basque' },
  { value: 'gl', label: 'Galician' },
  { value: 'ca', label: 'Catalan' },
  { value: 'is', label: 'Icelandic' },
  { value: 'ga', label: 'Irish' },
  { value: 'cy', label: 'Welsh' },
  { value: 'gd', label: 'Scottish Gaelic' },
];

export default function Language() {
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search)

  const [search, setsearch] = useState('');
  const [opens, setOpens] = useState(false);
  const [open, setOpen] = useState(false);
  const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
  const [deleteOpens, setDeleteOpens] = useState();
  const [order, setOrder] = useState('asc');
  const [selected, setSelected] = useState([]);
  const [orderBy, setOrderBy] = useState('name');
  const [filterName, setFilterName] = useState('');
  const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
  const [languageList, setLanguageList] = React.useState([]);
  const [totalCount, setTotalCount] = useState(0);
  const [id, setId] = useState('');
  const [lang, setLang] = useState('');
  const [status, setStatus] = React.useState(true);
  const [file, setFile] = useState();
  const [isSubmitting, setSubmitting] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [filters, setFilters] = useState({});
  const [isLoading, setIsLoading] = useState(true);

  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm')

  const style1 = {
    position: 'absolute',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    width: isMobile ? "90%" : 400,
    backgroundColor: 'white',
    borderRadius: '8px',
    boxShadow: '0px 4px 16px rgba(0, 0, 0, 0.2)',
    p: isMobile ? 2 : 4,
  };


  const [selectedOption, setSelectedOption] = useState({ value: '', label: '' });
  const handleLanguageChange = (event) => {
    const selectedOption = event.target.value;
    setSelectedOption(selectedOption);
  };

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let url = `module/translation/languages?page=${page}&_limit=${rowsPerPage}`;
      // if (search) {
      //   url += `&search=${search}`;
      //   setPage(1);
      // }
      if (search) url += `&search=${search}`;
      Object.entries(filters).forEach(([key, value]) => {
        if (value) url += `&${key}=${value}`;
      });
      const res = await axios.get(url);
      if (res.status === 200) {
        setLanguageList(res.data.data.language);
        setTotalCount(res.data.data.count);
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [page, rowsPerPage, order, orderBy, search, filters]);

  useEffect(() => {
    updateUrlParams({ page, limit: rowsPerPage });
  }, [page, rowsPerPage, search]);

  const openUpdateDialog = async (id, obj) => {
    setStatus(obj.status);
    setId(id);
    setSelectedOption({ value: obj.indexName, label: obj.name })
    setFile(null)
    setLang(obj.name);
    setOpen(true);
  };

  const openAddDialog = () => {
    setSelectedOption({ value: '', label: '' })
    setStatus(true);
    setFile(null)
    setOpens(true);
  };

  const AddLanguage = (event) => {
    setSubmitting(true)
    event.preventDefault();
    const formData = new FormData();
    if (file) {
      formData.append('file', file);
    }
    formData.append('name', selectedOption?.label);
    formData.append('indexName', selectedOption?.value);
    formData.append('status', status);

    const config = {
      headers: {
        'content-type': 'multipart/form-data',
      },
      onUploadProgress(progressEvent) {
        const percentCompleted = Math.round((progressEvent.loaded * 100) / progressEvent.total);
        setUploadProgress(percentCompleted);
      }
    };

    axios.post(`/module/translation/languages`, formData, config)
      .then((response) => {
        setSubmitting(false);
        setOpens(false);
        fetchData();
        setStatus(true);
        setOpen(false);
        setFile(null);
        setSelectedOption({ value: '', label: '' })
      })
      .catch((error) => {
        setSubmitting(false)
        console.error("Error uploading file: ", error);
      });
  }

  const UpdateLanguage = async () => {
    try {
      const res = await axios.put(`/module/admin/language/${id}`, { Language: lang });
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'success');
        setOpen(false);
        fetchData();

        // Update the languageList state with the updated language data
        const updatedLanguageList = languageList.map(item => {
          if (item.id === id) {
            return {
              ...item,
              name: lang // Update the language name
            };
          }
          return item;
        });
        setLanguageList(updatedLanguageList);
      }

    } catch (err) {
      if (err.response && err.response.data && err?.response?.data?.message) {
        GenerateToastConfig(err?.response?.data?.message);
      } else {
        GenerateToastConfig("An error occurred while updating the language.");
      }
    };
  };

  const deleteModal = (ids) => {
    sessionStorage.setItem("userId", ids)
    setDeleteOpens(true);
  }

  const deleteIcon = async () => {
    const ids = sessionStorage.getItem("userId")

    try {
      const res = await axios.delete(`/module/translation/languages/${ids}`);
      if (res.status === 200) {
        setDeleteOpens(false)
        GenerateToastConfig(res.data.message, 'info');
        fetchData();
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message, {
        position: 'top-right',
        autoClose: 5000,
        hideProgressBar: false,
        closeOnClick: true,
        pauseOnHover: true,
        draggable: true,
        progress: undefined,
        theme: 'light',
      });
    }
  };

  const handleRequestSort = (event, property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  const handleSelectAllClick = (event) => {
    if (event.target.checked) {
      const newSelecteds = languageList.map((n) => n.name);
      setSelected(newSelecteds);
      return;
    }
    setSelected([]);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage + 1);
  };

  const handleChangeRowsPerPage = (event) => {
    setPage(1);
    setRowsPerPage(parseInt(event.target.value, 10));
  };

  const handleFilterByName = (event) => {
    setPage(0);
    setFilterName(event.target.value);
  };

  const handleClick = () => {
    setStatus(!status);
  };

  function handleChange(event) {
    setFile(event.target.files[0]);
  }

  const handleDefault = async (id) => {
    try {
      const response = await axios.put(`/module/translation/set-default/${id}`)
      if (response?.status === 200) {
        GenerateToastConfig(response?.data?.message, 'success')
      } else {
        GenerateToastConfig(response?.data?.message)
      }
      const url = `module/translation/languages?page=${page}&_limit=${rowsPerPage}`
      const newDefaultValue = await axios.get(url)
      if (newDefaultValue?.status === 200) {
        setLanguageList(newDefaultValue?.data?.data?.language)
        setTotalCount(newDefaultValue?.data?.data?.count)
      }
    } catch (error) {
      console.error(error)
      GenerateToastConfig(error?.response?.data?.message)
    }
  }

  const ActionComponent = (cell) => {
    const value = cell?.getValue();
    const original = cell?.row?.original;
    const [anchorEl, setAnchorEl] = useState(null);
    const [menuRowId, setMenuRowId] = useState(null);

    const handleActionMenu = (event, rowId) => {
      setAnchorEl(event.currentTarget);
      setMenuRowId(rowId);
    };

    const handleActionMenuClose = () => {
      setAnchorEl(null);
      setMenuRowId(null);
    };

    return (
      <>
        <IconButton
          sx={{
            width: '37px',
            height: '37px',
            background: '#EBEBEB',
            color: 'black',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: '50%',
          }}
          onClick={(event) => handleActionMenu(event, value)}
        >
          <Iconify icon="mdi:dots-horizontal" />
        </IconButton>
        <Popover
          anchorEl={anchorEl}
          open={Boolean(anchorEl) && menuRowId === value}
          onClose={handleActionMenuClose}
          anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
          transformOrigin={{ vertical: 'top', horizontal: 'right' }}
          PaperProps={{
            sx: { width: 140 },
          }}
        >
          <MenuItem onClick={() => openUpdateDialog(value, original)}>
            <Iconify icon={'carbon:view'} sx={{ mr: 2 }} /> View
          </MenuItem>
          <a download={`${original?.indexName}.json`} href={`${BASE_URL}public/${original.file}`} alt="">
            <MenuItem >
              <Iconify icon={'heroicons-outline:download'} sx={{ mr: 2 }} /> Download
            </MenuItem>
          </a>
          {!original.default && <MenuItem onClick={() => deleteModal(value)} sx={{ color: 'error.main' }}>
            <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} /> Delete
          </MenuItem>}
        </Popover>
      </>
    );
  }

  const columns = [
    {
      header: i18?.SETTINGSLIST?.LANGUAGE || "Language",
      id: "name",
      accessorKey: "name",
      showFilter: true,
      cell: ({ row: { original } }) => (
        <div style={{ position: 'relative', display: 'flex', alignItems: 'center' }}>
          {original?.default && (
            <Label color="success" style={{ position: "absolute", right: 0 }}>
              {i18?.SETTINGSLIST?.DEFAULT || "Default"}
            </Label>
          )}
          <span>{original?.name || "---"}</span>
        </div>
      )
    },
    {
      header: i18?.SETTINGSLIST?.INDEX || "Index",
      id: "indexName",
      accessorKey: "indexName",
      showFilter: true,
      cell: ({ row }) => (row?.original?.indexName || "---")
    },
    {
      header: i18?.SETTINGSLIST?.STATUS || "Status",
      id: "status",
      accessorKey: "status",
      showFilter: false,
      cell: ({ row }) => row?.original?.status ? (
        <Label color="success">Active</Label>
      ) : (
        <Label color="error">Inactive</Label>
      ),
    },
    {
      header: i18?.SETTINGSLIST?.CREATED_AT || "Created At",
      id: "updatedAt",
      accessorKey: "updatedAt",
      cell: ({ row }) => (DateFormat(row?.original?.updatedAt) || "---")
    },
    {
      header: i18?.SETTINGSLIST?.DEFAULT || "Default",
      id: "default",
      accessorKey: "default",
      cell: ({ row: { original } }) => (
        <>
          {!original.default && (
            <Button
              variant="contained"
              sx={{ fontSize: "13px", marginLeft: "11px", padding: "3px 10px" }}
              onClick={() => handleDefault(original?._id)}
            >
              {i18?.SETTINGSLIST?.SET_DEFAULT || "Set Default"}
            </Button>
          )}
        </>
      )
    },
    {
      header: i18?.SETTINGSLIST?.ACTION || "Action",
      id: "action",
      accessorKey: "_id",
      cell: ActionComponent,
    },
  ]

  // const columns = useMemo(() => COLUMNS, [i18]);

  // const data = useMemo(() => languageList.map((language) => {
  //   return {
  //     name: language?.name,
  //     indexName: language?.indexName,
  //     status: language?.status,
  //     updatedAt: language?.updatedAt,
  //     action: language?._id,
  //     default: language?.default,
  //     file: language?.file,
  //   };
  // }), [languageList]);

  const handleFilterChange = (filterKey, value) => {
    setFilters((prev) => ({ ...prev, [filterKey]: value }));
    setPage(1);
  };

  return (
    <>
      <Helmet>
        <title> Language | Admin panel </title>
      </Helmet>
      {isMobile && <Stack direction="row" alignItems="center" style={{ marginBottom: "30px" }} justifyContent="space-between">
        <Typography variant="h4" gutterBottom>
          {i18?.SETTINGSLIST?.LIST_LANGUAGE || "List Language"}
        </Typography>
        <Button variant="contained" onClick={openAddDialog} startIcon={<Iconify icon="eva:plus-fill" />}>
          {i18?.SETTINGSLIST?.ADD_LANGUAGE || "Add Language"}
        </Button>
      </Stack>}
      {!isMobile && <Stack direction="row" alignItems="center" justifyContent="space-between" mb={0}>
        <Typography variant="h4" gutterBottom>
          {i18?.SETTINGSLIST?.LIST_LANGUAGE || "List Language"}
        </Typography>
        <Stack direction="row" alignItems="center">
          <UserListToolbar
            numSelected={selected.length}
            filterName={filterName}
            onFilterName={handleFilterByName}
            search={search}
            setsearch={setsearch}
          />
          <Button variant="contained" onClick={openAddDialog} startIcon={<Iconify icon="eva:plus-fill" />}>
            {i18?.SETTINGSLIST?.ADD_LANGUAGE || "Add Language"}
          </Button>
        </Stack>
      </Stack>}


      <Card>
        {isMobile && <UserListToolbar
          numSelected={selected.length}
          filterName={filterName}
          onFilterName={handleFilterByName}
          search={search}
          setsearch={setsearch}
        />}

        <Scrollbar>
          {/* <TanstackTable data={data} columns={columns} /> */}
          <TanstackTableV8
            data={languageList}
            columns={columns}
            filters={filters}
            isLoading={isLoading}
            onFilterChange={handleFilterChange}
          />
        </Scrollbar>

      </Card>

      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={totalCount || '0'}
        rowsPerPage={rowsPerPage}
        page={page - 1}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        sx={{
          '.MuiTablePagination-selectLabel': {
            marginTop: '12px',
          },
          '.MuiTablePagination-displayedRows': {
            marginTop: '12px',
          },
          '.MuiTablePagination-actions': {
            marginBottom: '6px',
          }
        }}
      />
      <Modal
        open={opens}
        onClose={() => setOpens(false)}
      >
        <form onSubmit={AddLanguage}>
          <Box sx={style1}>
            <Typography id="modal-modal-title" variant="h6" component="h2">
              {i18?.SETTINGSLIST?.ADD_LANGUAGE || "Add Language"}
            </Typography>
            <div className="mb-2 mt-2">
              <FormControl fullWidth>
                <InputLabel id="select-label">{i18?.SETTINGSLIST?.LANGUAGE || "Language"}</InputLabel>
                <Select
                  labelId="select-label"
                  id="select"
                  value={languageOptions.find(option => option.value === selectedOption.value) || ''}
                  onChange={handleLanguageChange}
                  label={i18?.SETTINGSLIST?.LANGUAGE || "Language"}
                >
                  {languageOptions?.map((each, index) => (
                    <MenuItem key={index} value={each}>{each?.label}</MenuItem>
                  ))}
                </Select>
              </FormControl>
            </div>
            <div>{i18?.SETTINGSLIST?.STATUS || "Status"}
              <Switch
                checked={status}
                onChange={handleClick}
                inputProps={{ 'aria-label': 'controlled' }}
              />
            </div>
            <div className='mt-3 mb-3'>
              <label htmlFor="file-upload">
                <input className='form-control-file' type="file" name="handle" accept=".json" id="file-upload" onChange={handleChange} required />
              </label>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <Button variant="contained" size="medium" color="primary" type="submit" disabled={isSubmitting}>
                {i18?.SETTINGSLIST?.ADD || "Add"}
              </Button>
            </div>
          </Box>
        </form>
      </Modal>


      <Modal
        open={open}
        onClose={() => setOpen(false)}
        aria-labelledby="modal-modal-title"
        aria-describedby="modal-modal-description"
      >
        <Box sx={style1}>
          <Typography id="modal-modal-title" variant="h6" component="h2">
            {i18?.SETTINGSLIST?.UPDATE_LANGUAGE || "Update Language"}
          </Typography>
          <div className="mb-2 mt-2">
            <FormControl fullWidth>
              <InputLabel id="select-label">{i18?.SETTINGSLIST?.LANGUAGE || "Language"}</InputLabel>
              <Select
                labelId="select-label"
                id="select"
                value={languageOptions.find(option => option.value === selectedOption.value) || ''}
                onChange={handleLanguageChange}
                label={i18?.SETTINGSLIST?.LANGUAGE || "Language"}
              >
                {languageOptions?.map((each, index) => (
                  <MenuItem key={index} value={each}>{each?.label}</MenuItem>
                ))}
              </Select>
            </FormControl>
          </div>
          <div>{i18?.SETTINGSLIST?.STATUS || "Status"}
            <Switch
              checked={status}
              onChange={handleClick}
              inputProps={{ 'aria-label': 'controlled' }}
            />
          </div>
          <div className='mt-3 mb-3'>
            <label htmlFor="file-upload">
              <input className='form-control-file' type="file" name="handle" accept=".json" id="file-upload" onChange={handleChange} required />
            </label>
          </div>
          <div style={{ display: 'flex', justifyContent: 'space-between' }}>
            <Button variant="contained" size="medium" color="primary" onClick={() => setOpen(false)}>
              {i18?.SETTINGSLIST?.CLOSE || "Close"}
            </Button>
            <Button variant="contained" size="medium" color="primary" onClick={AddLanguage} >
              {i18?.SETTINGSLIST?.UPDATE || "Update"}
            </Button>
          </div>
        </Box>
      </Modal>

      <DeleteModal
        isDeleteOpen={deleteOpens}
        handleClose={() => setDeleteOpens(false)}
        handleDelete={deleteIcon}
      />

    </>
  );
}
